_DIGITS = set('0123456789')


def _decode(token):
    # RFC 6901: '~1' -> '/' first, then '~0' -> '~'.
    return token.replace('~1', '/').replace('~0', '~')


def _tokens(pointer):
    if not pointer.startswith('/'):
        raise KeyError(pointer)
    return [_decode(t) for t in pointer[1:].split('/')]


def _as_index(token):
    if not token or any(c not in _DIGITS for c in token):
        raise KeyError(token)
    return int(token)


def _step(node, token):
    if isinstance(node, dict):
        return node[token]
    if isinstance(node, list):
        i = _as_index(token)
        if i >= len(node):
            raise KeyError(token)
        return node[i]
    raise KeyError(token)


def resolve(doc, pointer):
    if pointer == '':
        return doc
    node = doc
    for token in _tokens(pointer):
        node = _step(node, token)
    return node


def set_at(doc, pointer, value):
    tokens = _tokens(pointer)
    node = doc
    for token in tokens[:-1]:
        node = _step(node, token)
    last = tokens[-1]
    if isinstance(node, dict):
        node[last] = value
    elif isinstance(node, list):
        if last == '-':
            node.append(value)
        else:
            i = _as_index(last)
            if i >= len(node):
                raise KeyError(last)
            node[i] = value
    else:
        raise KeyError(last)

